// Bilingual annotations for the annotated samples other than pacs.008 (which
// keeps its own notes in xmlGuide.ts). Keys are a tag ("TxSts") or a path
// suffix ("StsRsnInf/Rsn/Cd") for tags whose meaning depends on where they sit;
// the longest matching suffix wins. "{value}" is replaced by the element's
// value in the sample. Codes cite ISO 20022 external code lists; their use is
// always defined by each scheme.

type Bi = [es: string, en: string]
export interface SampleNote {
  name: Bi
  meaning: Bi
  note: Bi
  explain?: Bi
  equivalent?: Bi
  parts?: [label: string, es: string, en: string][]
  concept?: string
}

const n = (name: Bi, meaning: Bi, note: Bi, extra: Partial<SampleNote> = {}): SampleNote => ({ name, meaning, note, ...extra })

