/** Longest matching path suffix first (with or without [n] indexes), then the bare tag. */
export function findSampleNote(tag: string, path: string): SampleNote | undefined {
  const plain = path.replace(/\[\d+\]/g, '')
  let best: string | undefined
  for (const key of Object.keys(sampleNotes)) {
    if (!key.includes('/')) continue
    const matches = path.endsWith(`/${key}`) || plain.endsWith(`/${key}`)
    if (matches && (!best || key.length > best.length)) best = key
  }
  return sampleNotes[best ?? tag]
}

/** Inserts the element's value; blocks (no value) drop the placeholder cleanly. */
export function fillValue(text: string, value: string) {
  return value ? text.replace(/\{value\}/g, value) : text.replace(/:? ?\(?\{value\}\)?/g, '').replace(/\s+\./g, '.')
}
